This project demonstrates how to export Rust in the form of a class to C++. Rust code: // src/lib.rs
pub struct Foo { data: i32,
} impl Foo { fn new(val: i32) -> Foo { Foo { data: val } } fn f(&self, a: i32, b: i32) -> i32 { self.data + a + b } fn set_field(&mut self, v: i32) { self.data = v; }
} Described as class: // src/cpp_glue.rs.in
foreign_class!(class Foo { self_type Foo; constructor Foo::new(_: i32) -> Foo; fn Foo::set_field(&mut self, _: i32); fn Foo::f(&self, _: i32, _: i32) -> i32; fn f2(_: i32) -> i32;
}); Usage from C++: // main.cpp Foo foo(5); int res = foo.f(1, 2);

